    for c in range(14):
        if c in [0, 3, 6, 9, 12]:  # Background
            row[c] = 6
        elif c in [2, 5, 8, 11]:  # Separator - always 0
            row[c] = 0
        elif c in [1, 4, 7, 10]:  # Content - use corrected pattern
            # Map content position to value
            pos = [1, 4, 7, 10].index(c)
            row[c] = content[pos]
        else:
            # Fallback to 6
            row[c] = 6

    output_grid.append(row.tolist())

# Output the grid as list of lists
